import { DomainError } from "./DomainError";
import { TaskStatus } from "./TaskStatus";

export class Task {
  public constructor(
    public readonly id: string,
    public readonly projectId: string,
    public readonly title: string,
    public readonly description: string,
    public readonly dueDate: Date | undefined,
    public readonly assigneeId: string | undefined,
    private taskStatus: TaskStatus = "todo",
  ) {
    if (!id || !projectId || !title.trim() || !description.trim()) {
      throw new DomainError("A task requires an id, project, title and description");
    }
  }

  public get status(): TaskStatus {
    return this.taskStatus;
  }

  public markDone(): void {
    if (this.taskStatus === "done") {
      throw new DomainError("A task that is done cannot be marked done again");
    }
    this.taskStatus = "done";
  }
}

